import { NextRequest, NextResponse } from 'next/server';

interface ApiPost {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
}

interface DeleteResponse {
  message: string;
}

interface ErrorResponse {
  error: string;
}

interface UpdatePostBody {
  title?: string;
  content?: string;
}

interface RouteContext {
  params: Promise<{ id: string }>;
}

function parsePostId(id: string): number | null {
  const parsedId = Number.parseInt(id, 10);

  if (Number.isNaN(parsedId)) {
    return null;
  }

  return parsedId;
}

export async function GET(
  _request: NextRequest,
  { params }: RouteContext,
): Promise<NextResponse<ApiPost | ErrorResponse>> {
  const { id } = await params;
  const postId = parsePostId(id);

  if (postId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post: ApiPost = {
    id: postId,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post, { status: 200 });
}

export async function PUT(
  request: NextRequest,
  { params }: RouteContext,
): Promise<NextResponse<ApiPost | ErrorResponse>> {
  const { id } = await params;
  const postId = parsePostId(id);

  if (postId === null) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  const body = (await request.json().catch(() => null)) as UpdatePostBody | null;

  const updatedPost: ApiPost = {
    id: postId,
    title: body?.title ?? "'`Post ${id}`,
    content: body?.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost, { status: 200 });
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteContext,
): Promise<NextResponse<DeleteResponse | ErrorResponse>> {
  const { id } = await params;
  const postId = parsePostId(id);

  if (postId === null) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json({ message: "'`Post ${postId} deleted successfully` }, { status: 200 });
}
