 1	import { NextRequest, NextResponse } from 'next/server';
 2	
 3	interface ApiPost {
 4	  id: number;
 5	  title: string;
 6	  content: string;
 7	  createdAt?: string;
 8	  updatedAt?: string;
 9	}
10	
11	interface DeleteResponse {
12	  message: string;
13	}
14	
15	interface ErrorResponse {
16	  error: string;
17	}
18	
19	interface UpdatePostBody {
20	  title?: string;
21	  content?: string;
22	}
23	
24	interface RouteContext {
25	  params: Promise<{ id: string }>;
26	}
27	
28	function parsePostId(id: string): number | null {
29	  const parsedId = Number.parseInt(id, 10);
30	
31	  if (Number.isNaN(parsedId)) {
32	    return null;
33	  }
34	
35	  return parsedId;
36	}
37	
38	export async function GET(
39	  _request: NextRequest,
40	  { params }: RouteContext,
41	): Promise<NextResponse<ApiPost | ErrorResponse>> {
42	  const { id } = await params;
43	  const postId = parsePostId(id);
44	
45	  if (postId === null) {
46	    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
47	  }
48	
49	  const post: ApiPost = {
50	    id: postId,
51	    title: `Post ${id}`,
52	    content: `This is the content for post ${id}`,
53	    createdAt: new Date().toISOString(),
54	  };
55	
56	  return NextResponse.json(post, { status: 200 });
57	}
58	
59	export async function PUT(
60	  request: NextRequest,
61	  { params }: RouteContext,
62	): Promise<NextResponse<ApiPost | ErrorResponse>> {
63	  const { id } = await params;
64	  const postId = parsePostId(id);
65	
66	  if (postId === null) {
67	    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
68	  }
69	
70	  const body = (await request.json().catch(() => null)) as UpdatePostBody | null;
71	
72	  const updatedPost: ApiPost = {
73	    id: postId,
74	    title: body?.title ?? `Post ${id}`,
75	    content: body?.content ?? `Updated content for post ${id}`,
76	    updatedAt: new Date().toISOString(),
77	  };
78	
79	  return NextResponse.json(updatedPost, { status: 200 });
80	}
81	
82	export async function DELETE(
83	  _request: NextRequest,
84	  { params }: RouteContext,
85	): Promise<NextResponse<DeleteResponse | ErrorResponse>> {
86	  const { id } = await params;
87	  const postId = parsePostId(id);
88	
89	  if (postId === null) {
90	    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
91	  }
92	
93	  return NextResponse.json({ message: `Post ${postId} deleted successfully` }, { status: 200 });
94	}

